public class Main {
    public static void main(String[] args) {
        String platform = "AWS";
        Object storage = null;
        Object database = null;
        Object compute = null;

        if (platform.equals("AWS")) {
            storage  = new AWSS3();
            database = new AWSDatabase();
            compute  = new AWSEC2();
        } else if (platform.equals("Azure")) {
            storage  = new AzureBlob();
            database = new AzureCosmos();
            compute  = new AzureVM();
        }

        System.out.println("Provisioned for " + platform + ": " +
                storage.getClass().getSimpleName() + ", " +
                database.getClass().getSimpleName() + ", " +
                compute.getClass().getSimpleName());
    }
}

