#include <bits/stdc++.h>
using namespace std;

class AWSS3 {};
class AWSDatabase {};
class AWSEC2 {};
class AzureBlob {};
class AzureCosmos {};
class AzureVM {};

int main() {
    string platform = "AWS";
    string storageName, databaseName, computeName;

    if (platform == "AWS") {
        storageName = "AWSS3";
        databaseName = "AWSDatabase";
        computeName = "AWSEC2";
    } else if (platform == "Azure") {
        storageName = "AzureBlob";
        databaseName = "AzureCosmos";
        computeName = "AzureVM";
    }

    cout << "Provisioned for " << platform << ": "
         << storageName << ", " << databaseName << ", " << computeName << endl;
    return 0;
}

