#include <bits/stdc++.h>
using namespace std;

class Packaging {
public:
    virtual void pack() = 0;
    virtual ~Packaging() = default;
};

class Shipping {
public:
    virtual void ship() = 0;
    virtual ~Shipping() = default;
};

class Invoice {
public:
    virtual void generate() = 0;
    virtual ~Invoice() = default;
};

class StandardPackaging : public Packaging {
public:
    void pack() override { cout << "Packing in standard brown box" << endl; }
};

class StandardShipping : public Shipping {
public:
    void ship() override { cout << "Shipping via postal service - 5 to 7 days" << endl; }
};

class StandardInvoice : public Invoice {
public:
    void generate() override { cout << "Generating standard invoice - base delivery charge" << endl; }
};

int main() {
    unique_ptr<Packaging> pkg = make_unique<StandardPackaging>();
    unique_ptr<Shipping> ship = make_unique<StandardShipping>();
    unique_ptr<Invoice> inv = make_unique<StandardInvoice>();
    pkg->pack();
    ship->ship();
    inv->generate();
    return 0;
}

