from abc import ABC, abstractmethod


class PaymentForm(ABC):
    @abstractmethod
    def collect_details(self):
        pass

    @abstractmethod
    def get_summary(self):
        pass


class PaymentProcessor(ABC):
    @abstractmethod
    def process(self, amount, form):
        pass


class PaymentFactory(ABC):
    @abstractmethod
    def create_form(self):
        pass

    @abstractmethod
    def create_processor(self):
        pass


class CheckoutService:
    def __init__(self, factory):
        self.factory = factory

    def checkout(self, amount):
        form = self.factory.create_form()
        processor = self.factory.create_processor()

        form.collect_details()
        processor.process(amount, form)


class CreditCardForm(PaymentForm):
    def __init__(self):
        self.card_number = "4111-1111-1111-1111"
        self.expiry = "12/26"

    def collect_details(self):
        print("Collecting credit card details...")
        print(f"Card Number: {self.card_number}")
        print(f"Expiry: {self.expiry}")

    def get_summary(self):
        return "CreditCard ending in 1111"


class CreditCardProcessor(PaymentProcessor):
    def process(self, amount, form):
        print("Processing via Visa/Mastercard network...")
        print(f"Charging {amount} to {form.get_summary()}")
        print("Transaction approved!")


class PayPalForm(PaymentForm):
    def __init__(self):
        self.email = "user@paypal.com"

    def collect_details(self):
        print("Redirecting to PayPal login...")
        print(f"PayPal Account: {self.email}")

    def get_summary(self):
        return f"PayPal account: {self.email}"


class PayPalProcessor(PaymentProcessor):
    def process(self, amount, form):
        print("Processing via PayPal API...")
        print(f"Charging {amount} to {form.get_summary()}")
        print("PayPal payment confirmed!")


class CreditCardFactory(PaymentFactory):
    def create_form(self):
        return CreditCardForm()

    def create_processor(self):
        return CreditCardProcessor()


class PayPalFactory(PaymentFactory):
    def create_form(self):
        return PayPalForm()

    def create_processor(self):
        return PayPalProcessor()


if __name__ == "__main__":
    print("=== Credit Card Checkout ===")
    credit_card = CheckoutService(CreditCardFactory())
    credit_card.checkout("$149.99")

    print()

    print("=== PayPal Checkout ===")
    paypal = CheckoutService(PayPalFactory())
    paypal.checkout("$149.99")

